	(3013, 33718, 'wprm_ingredients', 'a:2:{i:0;a:2:{s:11:\"ingredients\";a:4:{i:0;a:5:{s:6:\"amount\";s:5:\"1 1/2\";s:4:\"unit\";s:4:\"cups\";s:4:\"name\";s:6:\"coffee\";s:5:\"notes\";s:0:\"\";s:2:\"id\";i:120;}i:1;a:5:{s:6:\"amount\";s:3:\"1/4\";s:4:\"unit\";s:3:\"cup\";s:4:\"name\";s:7:\"cashews\";s:5:\"notes\";s:0:\"\";s:2:\"id\";i:121;}i:2;a:5:{s:6:\"amount\";s:1:\"1\";s:4:\"unit\";s:4:\"tbsp\";s:4:\"name\";s:5:\"honey\";s:5:\"notes\";s:0:\"\";s:2:\"id\";i:122;}i:3;a:5:{s:6:\"amount\";s:3:\"1/4\";s:4:\"unit\";s:3:\"tsp\";s:4:\"name\";s:4:\"salt\";s:5:\"notes\";s:0:\"\";s:2:\"id\";i:123;}}s:4:\"name\";s:14:\"For the coffee\";}i:1;a:2:{s:11:\"ingredients\";a:1:{i:0;a:5:{s:6:\"amount\";s:1:\"2\";s:4:\"unit\";s:4:\"tbsp\";s:4:\"name\";s:7:\"whiskey\";s:5:\"notes\";s:12:\"good quality\";s:2:\"id\";i:124;}}s:4:\"name\";s:20:\"For a more fun drink\";}}'),
	(3014, 33718, 'wprm_instructions', 'a:2:{i:0;a:2:{s:12:\"instructions\";a:1:{i:0;a:2:{s:4:\"text\";s:277:\"<p>Blend all ingredients for about 45 seconds in a high-powered blender. Start on a lower speed and gradually work your way up, ending with about 15 seconds on a very high speed to ensure smooth and creamy texture. Pour into a mug and enjoy, or chill for later (see notes)!</p>\";s:5:\"image\";i:33717;}}s:4:\"name\";s:0:\"\";}i:1;a:2:{s:12:\"instructions\";a:1:{i:0;a:2:{s:4:\"text\";s:199:\"<p>This is <b>bold text</b>, <i>italic text</i>, <u>underlined text</u>, <sup>superscript</sup>, <sub>subscript</sub>, and a <a href=\"google.com\" target=\"_blank\" rel=\"nofollow\">nofollow link</a>!</p>\";s:5:\"image\";i:0;}}s:4:\"name\";s:22:\"An instruction heading\";}}'),
