	(3040, 33720, 'wprm_ingredients', 'a:2:{i:0;a:2:{s:11:\"ingredients\";a:4:{i:0;a:5:{s:6:\"amount\";s:5:\"1 1/2\";s:4:\"unit\";s:4:\"cups\";s:4:\"name\";s:6:\"coffee\";s:5:\"notes\";s:0:\"\";s:2:\"id\";i:120;}i:1;a:5:{s:6:\"amount\";s:3:\"1/4\";s:4:\"unit\";s:3:\"cup\";s:4:\"name\";s:7:\"cashews\";s:5:\"notes\";s:7:\"roasted\";s:2:\"id\";i:121;}i:2;a:5:{s:6:\"amount\";s:1:\"1\";s:4:\"unit\";s:4:\"tbsp\";s:4:\"name\";s:5:\"honey\";s:5:\"notes\";s:0:\"\";s:2:\"id\";i:122;}i:3;a:5:{s:6:\"amount\";s:3:\"1/2\";s:4:\"unit\";s:3:\"tsp\";s:4:\"name\";s:15:\"coarse sea salt\";s:5:\"notes\";s:0:\"\";s:2:\"id\";i:125;}}s:4:\"name\";s:0:\"\";}i:1;a:2:{s:11:\"ingredients\";a:1:{i:0;a:5:{s:6:\"amount\";s:1:\"1\";s:4:\"unit\";s:3:\"cup\";s:4:\"name\";s:11:\"for serving\";s:5:\"notes\";s:0:\"\";s:2:\"id\";i:126;}}s:4:\"name\";s:21:\"An ingredient heading\";}}'),
	(3041, 33720, 'wprm_instructions', 'a:2:{i:0;a:2:{s:12:\"instructions\";a:1:{i:0;a:2:{s:4:\"text\";s:60:\"<p>Blend everything together! Minus the cup for serving.</p>\";s:5:\"image\";i:33717;}}s:4:\"name\";s:0:\"\";}i:1;a:2:{s:12:\"instructions\";a:1:{i:0;a:2:{s:4:\"text\";s:191:\"<p><b>Bold text</b>, <i>italic text</i>, <u>underlined text</u>, <sub>subscript</sub>, <sup>superscript</sup>, and a <a href=\"google.com\" target=\"_blank\" rel=\"nofollow\">nofollow link</a>.</p>\";s:5:\"image\";i:0;}}s:4:\"name\";s:22:\"An instruction heading\";}}'),
	(3042, 33720, 'wprm_notes', '<p><strong>Paragraph text: Notes about cold vs. hot cashew coffee:</strong> Cashews straight out the package should blend just fine with hot coffee (although if you’re particular, just give them an overnight soak). If you want to a COLD cashew coffee, you have two options.</p><ul><li>Unordered list item 1</li><li>Unordered list item 2</li></ul><ol><li>Ordered list item 1</li><li>Ordered list item 2</li></ol><p><strong>Bold text</strong>, <em>italic text</em>, and a <a href=\"http://google.com\">link</a>.</p><blockquote><p>A quote, because it\'s an option in the formatter... not that anyone would ever use it.</p></blockquote><p> </p>'),
