	(2378025, 4051, 'wprm_ingredients', 'a:1:{i:0;a:2:{s:11:\"ingredients\";a:11:{i:0;a:5:{s:6:\"amount\";s:4:\"2 32\";s:4:\"unit\";s:3:\"oz.\";s:4:\"name\";s:25:\"bags frozen broccoli cuts\";s:5:\"notes\";s:0:\"\";s:2:\"id\";i:1872;}i:1;a:5:{s:6:\"amount\";s:1:\"2\";s:4:\"unit\";s:4:\"cups\";s:4:\"name\";s:22:\"raw cashews or pepitas\";s:5:\"notes\";s:66:\"soaked for 2-8 hours if possible (*see note for quick-soak method)\";s:2:\"id\";i:482;}i:2;a:5:{s:6:\"amount\";s:1:\"3\";s:4:\"unit\";s:4:\"cups\";s:4:\"name\";s:37:\"water or plain unsweetened plant milk\";s:5:\"notes\";s:0:\"\";s:2:\"id\";i:1873;}i:3;a:5:{s:6:\"amount\";s:1:\"1\";s:4:\"unit\";s:10:\"tablespoon\";s:4:\"name\";s:10:\"miso paste\";s:5:\"notes\";s:8:\"optional\";s:2:\"id\";i:1830;}i:4;a:5:{s:6:\"amount\";s:1:\"1\";s:4:\"unit\";s:8:\"teaspoon\";s:4:\"name\";s:4:\"salt\";s:5:\"notes\";s:0:\"\";s:2:\"id\";i:299;}i:5;a:5:{s:6:\"amount\";s:1:\"2\";s:4:\"unit\";s:11:\"tablespoons\";s:4:\"name\";s:17:\"nutritional yeast\";s:5:\"notes\";s:0:\"\";s:2:\"id\";i:326;}i:6;a:5:{s:6:\"amount\";s:1:\"2\";s:4:\"unit\";s:11:\"tablespoons\";s:4:\"name\";s:19:\"apple cider vinegar\";s:5:\"notes\";s:40:\"lemon juice, or unsweetened rice vinegar\";s:2:\"id\";i:1198;}i:7;a:5:{s:6:\"amount\";s:1:\"1\";s:4:\"unit\";s:0:\"\";s:4:\"name\";s:12:\"yellow onion\";s:5:\"notes\";s:5:\"diced\";s:2:\"id\";i:642;}i:8;a:5:{s:6:\"amount\";s:1:\"8\";s:4:\"unit\";s:6:\"ounces\";s:4:\"name\";s:27:\"crimini or button mushrooms\";s:5:\"notes\";s:5:\"diced\";s:2:\"id\";i:337;}i:9;a:5:{s:6:\"amount\";s:0:\"\";s:4:\"unit\";s:0:\"\";s:4:\"name\";s:24:\"salt and pepper to taste\";s:5:\"notes\";s:0:\"\";s:2:\"id\";i:328;}i:10;a:5:{s:6:\"amount\";s:3:\"1-2\";s:4:\"unit\";s:0:\"\";s:4:\"name\";s:21:\"sleeves Ritz crackers\";s:5:\"notes\";s:81:\"crushed into crumbs, or substitute 2 GF plain bread crumbs for gluten-free option\";s:2:\"id\";i:343;}}s:4:\"name\";s:0:\"\";}}'),
	(2378026, 4051, 'wprm_instructions', 'a:2:{i:0;a:2:{s:12:\"instructions\";a:2:{i:0;a:2:{s:4:\"text\";s:99:\"<p>After soaking the cashews or pepitas*, drain, rinse, and add to a blender or food processor.</p>\";s:5:\"image\";i:0;}i:1;a:2:{s:4:\"text\";s:150:\"Add water/milk, miso, salt, nutritional yeast, and vinegar, and blend until smooth and creamy. If using a high-speed blender, no soaking is necessary.\";s:5:\"image\";i:0;}}s:4:\"name\";s:28:\"Make the Savory Cashew Cream\";}i:1;a:2:{s:12:\"instructions\";a:10:{i:0;a:2:{s:4:\"text\";s:34:\"Preheat the oven to 425 degrees F.\";s:5:\"image\";i:0;}i:1;a:2:{s:4:\"text\";s:215:\"Add the frozen broccoli to a 13x9 casserole dish and place it in the oven while it is preheating. Bake for 15-20 minutes until the broccoli is heated through and tender, stirring occasionally to ensure even heating.\";s:5:\"image\";i:0;}i:2;a:2:{s:4:\"text\";s:76:\"After the broccoli is cooked, set aside and reduce oven temperature to 350F.\";s:5:\"image\";i:0;}i:3;a:2:{s:4:\"text\";s:58:\"Preheat a large skillet or saucepan over medium-high heat.\";s:5:\"image\";i:0;}i:4;a:2:{s:4:\"text\";s:137:\"Add mushrooms and onions to the pan and cook for 5-6 minutes, until mushrooms have released their liquid and onions are browned and soft.\";s:5:\"image\";i:0;}i:5;a:2:{s:4:\"text\";s:67:\"Add cashew cream to the onion/mushroom mixture and stir to combine.\";s:5:\"image\";i:0;}i:6;a:2:{s:4:\"text\";s:103:\"Reduce heat to medium, and cook for 4-5 minutes until mixture has thickened slightly. Remove from heat.\";s:5:\"image\";i:0;}i:7;a:2:{s:4:\"text\";s:113:\"Pour the sauce over the broccoli in the casserole dish and stir to combine. Season to taste with salt and pepper.\";s:5:\"image\";i:0;}i:8;a:2:{s:4:\"text\";s:76:\"Spread cracker crumbs over the top of the broccoli mixture in an even layer.\";s:5:\"image\";i:0;}i:9;a:2:{s:4:\"text\";s:68:\"<p>Bake casserole, uncovered, for 30 minutes on the middle rack.</p>\";s:5:\"image\";i:0;}}s:4:\"name\";s:18:\"Make the casserole\";}}'),
	(2378027, 4051, 'wprm_notes', '<p>*Quick-soak method for raw cashews or pepitas: In a medium saucepan, add nuts or seeds along with enough water to cover. Bring to boil, then maintain a low boil for 15 minutes. Drain and rinse, and proceed with the recipe.</p>'),
